def main():
 # Portuguese court is only attached to Portugal during its actual Brazilian period.
 for r in rows:
  if r['name']=='Río de Janeiro':r['keyPeriods']={'PRT':[1808,1821],'BRA-EMPIRE':[1822,1889],'BRA':[1889,1960]}
 (OUT/'historical-places.json').write_text(json.dumps(dict(format='dated-urban-references',referenceDate='2026-10-26',records=rows,note='Sedes documentadas y ubicaciones urbanas, no perímetros ni poblaciones. Los traslados pueden producir más de una sede durante un mismo año. Referencias de coordenadas WGS84.'),ensure_ascii=False,indent=2)+'\n',encoding='utf8',newline='\n')
 print('Dated urban references',len(rows))
if __name__=='__main__':main()
